//
// Golden parity test for formatGeneralCssDouble against libc++
// std::to_chars(general). The fixture file is generated by compiling and
// running tools/gen_double_fixtures.cpp (same source as /tmp/gen_doubles.cpp)
// with clang++ -std=c++17 against the platform libc++:
//
//   clang++ -O2 -std=c++17 -o /tmp/gen_doubles tools/gen_double_fixtures.cpp
//   /tmp/gen_doubles > /tmp/double_fixtures.txt
//
// When the file is absent the test is skipped, so normal builds don't depend
// on a local clang.

package dev.calibre.viewer.parser

import dev.calibre.viewer.parser.transform.formatGeneralCssDouble
import java.io.File
import kotlin.test.assertEquals
import org.junit.jupiter.api.Assumptions.assumeTrue
import org.junit.jupiter.api.Test

class FormatDoubleParityTest {

    @Test
    fun `matches libc++ to_chars general on the golden fixtures`() {
        val fixture = File("/tmp/double_fixtures.txt")
        assumeTrue(fixture.isFile) { "fixtures not generated on this machine" }
        var n = 0
        var firstMismatch: String? = null
        for (line in fixture.readLines()) {
            if (line.isEmpty()) continue
            val sp = line.indexOf(' ')
            val bits = java.lang.Long.parseUnsignedLong(line.substring(0, sp), 16)
            val expected = line.substring(sp + 1)
            val d = java.lang.Double.longBitsToDouble(bits)
            val actual = formatGeneralCssDouble(d)
            n++
            if (actual != expected && firstMismatch == null) {
                firstMismatch = "bits=%s input=%.17g expected=<%s> actual=<%s>"
                    .format(line.substring(0, sp), d, expected, actual)
            }
        }
        assumeTrue(n > 0) { "empty fixture file" }
        assertEquals(null, firstMismatch, "libc++ divergence ($n samples): $firstMismatch")
    }
}
